use serde_json::{json,Value};
#[test]fn cli_import_search_reopen_and_invalid_operations_preserve_saved_data(){
 let folder=std::env::temp_dir().join(format!("fitig-semantic-cli-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&folder).unwrap();let db=folder.join("crawl.sqlite");
 {let c=rusqlite::Connection::open(&db).unwrap();c.execute_batch("CREATE TABLE pages(url TEXT PRIMARY KEY,json TEXT);CREATE TABLE frontier(url TEXT PRIMARY KEY,depth INTEGER,state TEXT);CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT);INSERT INTO metadata VALUES('seed','https://e.test/');").unwrap();let p=fitig_engine::Page{url:"https://e.test/".into(),title:"שלום".into(),..Default::default()};c.execute("INSERT INTO pages VALUES(?1,?2)",rusqlite::params![p.url,serde_json::to_string(&p).unwrap()]).unwrap();}
 let input=folder.join("input.json");std::fs::write(&input,json!({"version":1,"model":"owned-model","documents":[{"url":"https://e.test/","vector":[4,3]}]}).to_string()).unwrap();let run=|command:&str,file:Option<&std::path::Path>|{let mut c=std::process::Command::new(env!("CARGO_BIN_EXE_fitig-engine"));c.args([command,"--db"]).arg(&db);if let Some(file)=file{c.arg("--file").arg(file);}c.output().unwrap()};assert!(run("semantic-import",Some(&input)).status.success());
 let query=folder.join("query.json");std::fs::write(&query,json!({"model":"owned-model","query_vector":[1,0],"label":"שאילתה","top_k":1,"minimum_score":0}).to_string()).unwrap();let output=run("semantic-search",Some(&query));assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let report:Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(report["rows"][0]["score"],0.8);assert_eq!(report["rows"][0]["title"],"שלום");
 let bytes=std::fs::read(&db).unwrap();assert!(run("semantic-results",None).status.success());assert_eq!(std::fs::read(&db).unwrap(),bytes);std::fs::write(&query,"{}").unwrap();assert!(!run("semantic-search",Some(&query)).status.success());assert_eq!(std::fs::read(&db).unwrap(),bytes);assert!(!run("semantic-results",Some(&input)).status.success());assert_eq!(std::fs::read(&db).unwrap(),bytes);
 assert!(folder.starts_with(std::env::temp_dir()));std::fs::remove_dir_all(folder).unwrap();
}
